import docx

doc = docx.Document('/filesystem/CFDME-2025-041_transient_solve_disposition_revA.docx')
print(f'Total paragraphs: {len(doc.paragraphs)}')
print(f'Total tables: {len(doc.tables)}')

word_count = sum(len(p.text.split()) for p in doc.paragraphs)
for t in doc.tables:
    for row in t.rows:
        for c in row.cells:
            word_count += sum(len(p.text.split()) for p in c.paragraphs)

print(f'Total word count: {word_count}')

print('\nCheck for key strings:')
checks = [
    '0.87 Hz', '1.15 s', '0.41%', 'Cetegen', '3.00 m',
    'fireFoam', 'controlDict', '0.0460 s', '31.00 s',
    '4h 27m', '26h 44m', '6h 41m', '5h 45m',
    '11,214,862', 'OAS-WUI-01_revC', 'D*/dx', '7.52', 'Pope', '84%',
    'atmBoundaryLayerInletVelocity', '8.00 m/s', '6.10 m', '0.03 m',
    'CFD thermal analysis only. Fire-resistance rating certified separately by others.',
    'Marguerite Falk, PE', '42798', 'Gordon Selby, PE', '48213', '10/10/2025'
]

for chk in checks:
    found = False
    for p in doc.paragraphs:
        if chk in p.text:
            found = True
            break
    if not found:
        for t in doc.tables:
            for row in t.rows:
                for c in row.cells:
                    if chk in c.text:
                        found = True
                        break
                if found:
                    break
            if found:
                break
    print(f'  [{ \"PASS\" if found else \"FAIL\" }] \"{chk}\"')
